package main.game.maze.common.remains;

import java.util.Locale;
import java.util.function.Predicate;
import main.game.maze.common.graphics.DamageStateResolver;

/**
 * Picks the remains sprite for a killed enemy (sprites generated by
 * {@code tools/sprite-gen/RemainsSpriteGenerator.java}):
 * <ul>
 *   <li>{@link DeathCause#FIRE}: {@code remains/burned-N.png}, shared by all enemies (N chosen by seed)</li>
 *   <li>{@link DeathCause#SHOT}: {@code remains/<variant>-shot.png}, else {@code remains/generic-shot.png}</li>
 *   <li>{@link DeathCause#CRUSHED}: {@code remains/<variant>-crushed.png}, else {@code remains/generic-crushed.png}</li>
 *   <li>{@link DeathCause#OTHER}: none</li>
 * </ul>
 * The variant comes from the enemy sprite path ({@code zombie1-down.png} &rarr; {@code zombie1}).
 */
public final class RemainsSpriteResolver {

    public static final String REMAINS_DIR = "/main/game/maze/remains/";
    public static final int BURNED_VARIANTS = 3;

    private static final String[] SUFFIXES = {
            "-left", "-right", "-up", "-down", "-damaged", "-bleeding", "-tired"};

    private final Predicate<String> resourceExists;

    /** @param resourceExists answers whether a remains sprite path can be loaded */
    public RemainsSpriteResolver(Predicate<String> resourceExists) {
        this.resourceExists = resourceExists;
    }

    /** Resolver that checks the classpath relative to {@code anchor}. */
    public static RemainsSpriteResolver classpath(Class<?> anchor) {
        return new RemainsSpriteResolver(path -> DamageStateResolver.resourceExists(anchor, path));
    }

    /**
     * @param cause      how the enemy died
     * @param bodySprite the enemy sprite path (any direction or damage state), may be null
     * @param seed       varies the coal pile between enemies
     * @return the remains sprite path, or {@code null} when the death leaves nothing
     */
    public String spriteFor(DeathCause cause, String bodySprite, long seed) {
        if (cause == null || !cause.leavesRemains()) {
            return null;
        }
        if (cause == DeathCause.FIRE) {
            return REMAINS_DIR + "burned-" + (1 + Math.floorMod(seed, BURNED_VARIANTS)) + ".png";
        }
        String kind = cause == DeathCause.SHOT ? "shot" : "crushed";
        String variant = variantOf(bodySprite);
        if (variant != null) {
            String own = REMAINS_DIR + variant + "-" + kind + ".png";
            if (resourceExists.test(own)) {
                return own;
            }
        }
        return REMAINS_DIR + "generic-" + kind + ".png";
    }

    /** {@code /main/game/maze/zombie2-damaged-left.png} &rarr; {@code zombie2}; null for blank paths. */
    static String variantOf(String bodySprite) {
        if (bodySprite == null || bodySprite.isBlank()) {
            return null;
        }
        String name = bodySprite.substring(Math.max(bodySprite.lastIndexOf('/'), bodySprite.lastIndexOf('\\')) + 1);
        int dot = name.lastIndexOf('.');
        String stem = (dot >= 0 ? name.substring(0, dot) : name).toLowerCase(Locale.ROOT);
        boolean stripped = true;
        while (stripped) {
            stripped = false;
            for (String suffix : SUFFIXES) {
                if (stem.endsWith(suffix)) {
                    stem = stem.substring(0, stem.length() - suffix.length());
                    stripped = true;
                }
            }
        }
        return stem.isEmpty() ? null : stem;
    }
}
